import * as React from 'react';
import { useState, useEffect, useRef } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Sparkles, MapPin, Clock } from 'lucide-react';
import { FEMALE_NAMES, DISTRICT_LABELS, toTitleCase } from '../constants';

interface ActivityToastsProps {
  isActive: boolean;
}

interface NotificationData {
  id: string;
  name: string;
  age: number;
  location: string;
  action: string;
  time: string;
}

const ACTIONS = [
  "acabou de partilhar a sua história.",
  "adicionou um novo testemunho.",
  "partilhou como se sente.",
  "juntou-se ao movimento."
];

export const ActivityToasts: React.FC<ActivityToastsProps> = ({ isActive }) => {
  const [notification, setNotification] = useState<NotificationData | null>(null);
  const maxNotifications = 4; // Show only a few to not be annoying
  const countRef = useRef(0);
  const timeoutRef = useRef<NodeJS.Timeout | null>(null);

  const generateNotification = (): NotificationData => {
    const randomName = FEMALE_NAMES[Math.floor(Math.random() * FEMALE_NAMES.length)];
    const randomAge = Math.floor(Math.random() * (60 - 24 + 1)) + 24;
    const randomDistrict = DISTRICT_LABELS[Math.floor(Math.random() * DISTRICT_LABELS.length)];
    const randomAction = ACTIONS[Math.floor(Math.random() * ACTIONS.length)];

    return {
      id: Math.random().toString(36).substr(2, 9),
      name: randomName,
      age: randomAge,
      location: toTitleCase(randomDistrict.name),
      action: randomAction,
      time: "Agora mesmo"
    };
  };

  useEffect(() => {
    if (!isActive) return;

    const scheduleNext = () => {
      if (countRef.current >= maxNotifications) return;

      // Random delay between 4s and 12s
      const delay = Math.floor(Math.random() * 8000) + 4000;

      timeoutRef.current = setTimeout(() => {
        const newNotif = generateNotification();
        setNotification(newNotif);
        countRef.current += 1;

        // Hide after 5 seconds
        setTimeout(() => {
          setNotification(null);
          // Schedule the next one after hiding
          scheduleNext();
        }, 5000);
      }, delay);
    };

    scheduleNext();

    return () => {
      if (timeoutRef.current) clearTimeout(timeoutRef.current);
    };
  }, [isActive]);

  return (
    <div className="fixed bottom-24 left-4 md:bottom-10 md:left-10 z-40 pointer-events-none flex flex-col gap-2">
      <AnimatePresence mode="wait">
        {notification && (
          <motion.div
            key={notification.id}
            initial={{ opacity: 0, y: 20, scale: 0.95, filter: 'blur(10px)' }}
            animate={{ opacity: 1, y: 0, scale: 1, filter: 'blur(0px)' }}
            exit={{ opacity: 0, y: -10, scale: 0.95, filter: 'blur(10px)' }}
            transition={{ type: "spring", stiffness: 400, damping: 30 }}
            className="pointer-events-auto bg-white/80 backdrop-blur-xl border border-white/60 shadow-2xl shadow-black/5 rounded-2xl p-4 pr-6 flex items-start gap-3.5 max-w-[280px] md:max-w-xs"
          >
            {/* Icon Box */}
            <div className="relative shrink-0 mt-0.5">
              <div className="w-8 h-8 rounded-full bg-gradient-to-br from-[#6BAE2E] to-[#2E8B57] flex items-center justify-center text-white shadow-sm">
                <Sparkles size={14} className="fill-white/20" />
              </div>
              <span className="absolute -top-1 -right-1 flex h-2.5 w-2.5">
                <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-green-400 opacity-75"></span>
                <span className="relative inline-flex rounded-full h-2.5 w-2.5 bg-green-500 border border-white"></span>
              </span>
            </div>

            {/* Content */}
            <div className="flex flex-col">
              <div className="flex items-baseline gap-1.5 mb-0.5">
                <span className="text-sm font-bold text-gray-900 leading-none">
                  {notification.name}, {notification.age}
                </span>
              </div>

              <p className="text-xs text-gray-600 leading-snug mb-2">
                {notification.action}
              </p>

              <div className="flex items-center gap-3">
                <div className="flex items-center gap-1 text-[10px] font-medium text-gray-400 uppercase tracking-wide">
                  <MapPin size={10} />
                  <span>{notification.location}</span>
                </div>
                <div className="flex items-center gap-1 text-[10px] font-medium text-gray-400 uppercase tracking-wide">
                  <Clock size={10} />
                  <span>{notification.time}</span>
                </div>
              </div>
            </div>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
};

import * as React from 'react';
import { useState, useEffect } from 'react';
import { motion, AnimatePresence, useMotionValue, useSpring, useTransform, useInView, Variants } from 'framer-motion';
import { Info, X } from 'lucide-react';
import { Header } from './components/Header';
import { PortugalMap } from './components/PortugalMap';
import { CTAButton } from './components/CTAButton';
import { ShareStoryModal } from './components/ShareStoryModal';
import { IntroOverlay } from './components/IntroOverlay';
import { ActivityToasts } from './components/ActivityToasts';
import { TESTIMONIALS, Testimonial } from './constants';

// Hook to detect mobile screen size
const useIsMobile = () => {
    const [isMobile, setIsMobile] = useState(false);
    useEffect(() => {
        const checkMobile = () => setIsMobile(window.innerWidth < 768);
        checkMobile();
        window.addEventListener('resize', checkMobile);
        return () => window.removeEventListener('resize', checkMobile);
    }, []);
    return isMobile;
};

// Animated Counter Component
const Counter = ({ value }: { value: number }) => {
  // Slower, smoother spring for better visual of the counting up
  const spring = useSpring(0, { mass: 1, stiffness: 35, damping: 25 });
  const display = useTransform(spring, (current) => `+${Math.floor(current).toLocaleString()}`);

  useEffect(() => {
    spring.set(value);
  }, [value, spring]);

  return (
    <motion.span 
        className="bg-clip-text text-transparent bg-gradient-to-r from-[#6BAE2E] to-[#0872B1]"
    >
        {display}
    </motion.span>
  );
};

const App: React.FC = () => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [showLegal, setShowLegal] = useState(false);
  const [introActive, setIntroActive] = useState(true);
  const [testimonials, setTestimonials] = useState<Testimonial[]>(TESTIMONIALS);
  const isMobile = useIsMobile();

  // Base count to match the requested ~2590 range + dynamic additions
  const BASE_COUNT = 2590;
  const currentCount = BASE_COUNT + (testimonials.length - TESTIMONIALS.length);

  // Parallax Logic
  const mouseX = useMotionValue(0);
  const mouseY = useMotionValue(0);

  // Smooth spring animation for mouse movement
  const springConfig = { damping: 25, stiffness: 120, mass: 0.5 };
  const smoothX = useSpring(mouseX, springConfig);
  const smoothY = useSpring(mouseY, springConfig);

  // Transform values for parallax layers (Desktop Only)
  const mapX = useTransform(smoothX, [-0.5, 0.5], [10, -10]);
  const mapY = useTransform(smoothY, [-0.5, 0.5], [10, -10]);
  const contentX = useTransform(smoothX, [-0.5, 0.5], [25, -25]);
  const contentY = useTransform(smoothY, [-0.5, 0.5], [25, -25]);

  const handleMouseMove = (e: React.MouseEvent) => {
    if (isMobile || introActive) return;
    const { innerWidth, innerHeight } = window;
    const x = (e.clientX / innerWidth) - 0.5;
    const y = (e.clientY / innerHeight) - 0.5;

    mouseX.set(x);
    mouseY.set(y);
  };

  const handleAddStory = (newStory: Testimonial) => {
    setTestimonials(prev => [...prev, newStory]);
  };

  // Staggered Animation Variants
  const containerVariants: Variants = {
    hidden: { opacity: 0 },
    visible: {
      opacity: 1,
      transition: {
        staggerChildren: 0.15,
        delayChildren: 0.2,
      },
    },
  };

  const itemVariants: Variants = {
    hidden: { opacity: 0, y: 20 },
    visible: { 
      opacity: 1, 
      y: 0,
      transition: { type: "spring", stiffness: 50, damping: 15 }
    },
  };

  return (
    <div 
      className="relative h-[100dvh] w-full bg-[#F9FAFB] text-gray-900 overflow-hidden font-sans selection:bg-primary/20 flex flex-col md:block"
      onMouseMove={handleMouseMove}
    >
      {/* Intro Overlay Component */}
      <IntroOverlay onComplete={() => setIntroActive(false)} />

      {/* Activity Toasts (Social Proof) */}
      <ActivityToasts isActive={!introActive} />

      {/* Modal */}
      <ShareStoryModal 
        isOpen={isModalOpen} 
        onClose={() => setIsModalOpen(false)} 
        onAddStory={handleAddStory}
      />

      <Header />

      {/* Main Content Container with conditional blur */}
      <div 
        className={`w-full h-full transition-all duration-1000 ${introActive ? 'blur-[16px] pointer-events-none scale-[1.02] brightness-75' : 'blur-0'}`}
      >
        {/* --- CONTENT LAYER --- */}
        <motion.main 
          className={`
              relative z-20 
              w-full flex-none
              pt-20 pb-4 px-6
              bg-[#F9FAFB] md:bg-transparent
              md:absolute md:inset-0 md:h-full md:flex md:flex-col md:justify-center md:px-16 lg:px-24 md:pointer-events-none md:pt-0
          `}
          style={!isMobile ? { x: contentX, y: contentY } : {}}
        >
          <div className="pointer-events-auto max-w-xl mx-auto md:mx-0 flex flex-col items-center md:items-start text-center md:text-left">
              <motion.div
                variants={containerVariants}
                initial="hidden"
                animate={!introActive ? "visible" : "hidden"}
              >
                  <motion.h1 
                    variants={itemVariants}
                    className="text-3xl sm:text-4xl md:text-6xl lg:text-7xl font-bold leading-[1.1] tracking-tight mb-3 md:mb-6 text-gray-900"
                  >
                    Cada corpo <br className="hidden md:block"/>
                    <span className="md:hidden"> </span>
                    conta uma <br className="hidden md:block"/>
                    <span className="bg-clip-text text-transparent bg-gradient-to-r from-[#6BAE2E] via-[#2A9D8F] to-[#0872B1] animate-pulse-slow">
                        história.
                    </span>
                  </motion.h1>

                  <motion.p 
                    variants={itemVariants}
                    className="text-sm sm:text-base md:text-lg text-gray-600 mb-8 md:mb-12 leading-relaxed font-normal max-w-md mx-auto md:mx-0"
                  >
                    Estas são histórias reais. De mulheres reais.
                  </motion.p>

                  <div className="flex flex-col items-center md:items-start gap-8 md:gap-12">
                      <motion.div variants={itemVariants} className="scale-90 md:scale-100 origin-center md:origin-left">
                           <CTAButton onClick={() => setIsModalOpen(true)} />
                      </motion.div>

                      {/* Social Proof Section */}
                      <motion.div 
                        variants={itemVariants}
                        className="flex items-center gap-4 md:gap-5 pt-4 md:pt-6 border-t border-gray-200/60 w-full max-w-xs md:max-w-full justify-center md:justify-start"
                      >
                          <div className="flex -space-x-3">
                          {[
                              "https://images.unsplash.com/photo-1494790108377-be9c29b29330?auto=format&fit=crop&w=64&h=64&q=80",
                              "https://images.unsplash.com/photo-1573496359142-b8d87734a5a2?auto=format&fit=crop&w=64&h=64&q=80",
                              "https://images.unsplash.com/photo-1534528741775-53994a69daeb?auto=format&fit=crop&w=64&h=64&q=80",
                              "https://images.unsplash.com/photo-1531746020798-e6953c6e8e04?auto=format&fit=crop&w=64&h=64&q=80"
                          ].map((src, i) => (
                              <div key={i} className="w-9 h-9 md:w-11 md:h-11 rounded-full border-[3px] border-white shadow-sm overflow-hidden bg-gray-100">
                              <img 
                                  src={src} 
                                  alt={`Mulher real ${i+1}`} 
                                  className="w-full h-full object-cover" 
                              />
                              </div>
                          ))}
                          </div>
                          <div className="flex flex-col text-left justify-center">
                              <span className="text-xl md:text-2xl font-black leading-none mb-1 tracking-tight">
                                  <Counter value={currentCount} />
                              </span>
                              <span className="text-[10px] md:text-xs text-gray-500 font-bold uppercase tracking-wider">de Histórias Reais</span>
                          </div>
                      </motion.div>
                  </div>
              </motion.div>
          </div>
        </motion.main>

        {/* --- BACKGROUND/MAP LAYER --- */}
        <motion.div 
          className={`
              relative z-0 
              flex-1 w-full min-h-0
              md:absolute md:inset-0 md:scale-[1.02]
          `}
          initial={{ opacity: 0, scale: 1.05 }}
          animate={{ opacity: 1, scale: 1.02 }}
          transition={{ duration: 1.5, ease: "easeOut" }}
          style={!isMobile ? { x: mapX, y: mapY } : {}}
        >
          <PortugalMap testimonials={testimonials} />
        </motion.div>

        {!isMobile && (
            <div className="absolute inset-0 z-10 bg-gradient-to-r from-[#F9FAFB] via-[#F9FAFB]/80 to-transparent pointer-events-none w-[90%] md:w-[65%] lg:w-[55%]" />
        )}

        <motion.div 
          className="fixed top-6 right-6 md:right-12 z-50 hidden md:flex flex-col items-end gap-2"
          style={!isMobile ? { x: contentX, y: contentY } : {}}
        >
          <motion.button 
              onClick={() => setShowLegal(!showLegal)}
              whileHover={{ scale: 1.05 }}
              whileTap={{ scale: 0.95 }}
              className={`
                  flex items-center gap-2 px-3 py-1.5 rounded-full transition-all duration-300 text-[10px] font-bold tracking-wider uppercase backdrop-blur-sm border
                  ${showLegal 
                      ? 'bg-gray-900 text-white border-gray-900 shadow-lg' 
                      : 'bg-white/40 text-gray-400 border-transparent hover:bg-white hover:text-gray-600 hover:shadow-md hover:border-gray-100'
                  }
              `}
          >
              <Info size={14} strokeWidth={2.5} />
              <span>Aviso Legal</span>
          </motion.button>

          <AnimatePresence>
              {showLegal && (
                  <motion.div
                      initial={{ opacity: 0, y: -10, scale: 0.95, transformOrigin: 'top right' }}
