const getRandomItem = <T>(arr: T[]): T => arr[Math.floor(Math.random() * arr.length)];

// Context-aware age generator to match text content
const getSmartAge = (themeLabel: string, text: string): number => {
  let minAge = 25;
  let maxAge = 68;

  // 1. Theme constraints
  if (themeLabel === 'Menopausa') {
    minAge = 45;
    maxAge = 65;
  } else if (themeLabel === 'Longevidade') {
    minAge = 50;
    maxAge = 75;
  } else if (themeLabel === 'Ossos e Articulações') {
    minAge = 45;
  }

  // 2. Text context scanning (overrides theme min if text implies older)

  // "aos 45", "aos 50", etc.
  const aosMatch = text.match(/aos (\d+)/);
  if (aosMatch && aosMatch[1]) {
     minAge = Math.max(minAge, parseInt(aosMatch[1], 10));
  }

  // "fiz 40", "fiz 50", etc.
  const fizMatch = text.match(/fiz (\d+)/);
  if (fizMatch && fizMatch[1]) {
     minAge = Math.max(minAge, parseInt(fizMatch[1], 10));
  }

  // "depois dos 50", "nos 40", etc.
  const dosMatch = text.match(/(?:dos|nos) (\d+)/);
  if (dosMatch && dosMatch[1]) {
     minAge = Math.max(minAge, parseInt(dosMatch[1], 10));
  }

  // Safety cap to ensure valid range
  if (maxAge <= minAge) maxAge = minAge + 10;

  return Math.floor(Math.random() * (maxAge - minAge + 1)) + minAge;
};

const GENERATED_TESTIMONIALS: any[] = [];
// Increased stories per district to add more content
const STORIES_PER_DISTRICT = 50; 

const QUOTIDIANO_THEME = THEMES.find(t => t.label === "Quotidiano")!;
// Filter out Quotidiano from standard list to manually control probability
const HEALTH_THEMES = THEMES.filter(t => t.label !== "Quotidiano");

// Generate ensuring complete coverage of DISTRICTS only
DISTRICT_LABELS.forEach((district) => {
  const locationName = toTitleCase(district.name);
  for (let i = 0; i < STORIES_PER_DISTRICT; i++) {

    // Logic for Split
    // 40% Chance for "Quotidiano" (Increased from 30%), 60% for existing Health themes
    const isQuotidiano = Math.random() < 0.4;
    const theme = isQuotidiano ? QUOTIDIANO_THEME : getRandomItem(HEALTH_THEMES);

    // Safety fallback
    const templates = TEMPLATES[theme.label] || ["A minha história é única."];
    const text = getRandomItem(templates);
    const age = getSmartAge(theme.label, text);

    GENERATED_TESTIMONIALS.push({
      id: `gen-${district.name}-${Math.random().toString(36).substr(2, 6)}`,
      author: `${getRandomItem(FEMALE_NAMES)}, ${age}`,
      location: locationName,
      tag: theme.label,
      text: text,
      icon: theme.icon,
      createdAt: getRandomDate(1, 120) 
    });
  }
});

const RAW_COMBINED = [
    ...GENERATED_TESTIMONIALS
];

export const TESTIMONIALS: Testimonial[] = RAW_COMBINED.map((t) => {
  const baseCoords = CITIES[t.location] || CITIES['Portugal'];
  const { lat, lng } = getSmartCoords(t.location, baseCoords.lat, baseCoords.lng);
  return {
    ...t,
    lat,
    lng,
    visibilityRank: Math.random() 
  };
});

export const getCoordsForLocation = (locationName: string): { lat: number, lng: number } => {
  const norm = locationName.trim();
  let cityKey = Object.keys(CITIES).find(k => k.toLowerCase() === norm.toLowerCase());
  const base = cityKey ? CITIES[cityKey] : CITIES['Portugal'];
  return getSmartCoords(cityKey || locationName, base.lat, base.lng);
}

