                    <span className="font-bold text-gray-900">{visibleTestimonials.length} histórias</span>
                </div>
            </div>
          </motion.div>
        )}
      </AnimatePresence>

      <div className="absolute inset-0 z-0 bg-transparent">
        <MapContainer 
            center={[39.6, -7.0]} 
            zoom={7} 
            minZoom={5}
            maxBounds={portugalBounds}
