export const IntroOverlay: React.FC<{ onComplete: () => void }> = ({ onComplete }) => {
  const [index, setIndex] = useState(0);
  const [isVisible, setIsVisible] = useState(true);
  const [isAnimating, setIsAnimating] = useState(false);

  const lastScrollTime = useRef(0);

  const handleNext = useCallback(() => {
    if (isAnimating) return;
    if (index < SLIDES.length - 1) {
      setIsAnimating(true);
      setIndex(prev => prev + 1);
      setTimeout(() => setIsAnimating(false), 650); 
    } else {
      setIsVisible(false);
      setTimeout(onComplete, 600);
    }
  }, [index, isAnimating, onComplete]);

  const handlePrev = useCallback(() => {
    if (isAnimating || index === 0) return;
    setIsAnimating(true);
    setIndex(prev => prev - 1);
    setTimeout(() => setIsAnimating(false), 650);
  }, [index, isAnimating]);

  useEffect(() => {
    const handleKey = (e: KeyboardEvent) => {
      if (e.key === 'ArrowRight' || e.key === 'Enter' || e.key === ' ') handleNext();
      if (e.key === 'ArrowLeft') handlePrev();
    };
    window.addEventListener('keydown', handleKey);
    return () => window.removeEventListener('keydown', handleKey);
  }, [handleNext, handlePrev]);

  useEffect(() => {
    const handleWheel = (e: WheelEvent) => {
      const now = Date.now();
      if (now - lastScrollTime.current < 700) return; 
      if (Math.abs(e.deltaY) > 20) {
        lastScrollTime.current = now;
        e.deltaY > 0 ? handleNext() : handlePrev();
      }
    };
    window.addEventListener('wheel', handleWheel);
    return () => window.removeEventListener('wheel', handleWheel);
  }, [handleNext, handlePrev]);

  const currentSlide = SLIDES[index];

  const contentWords = useMemo(() => {
    const text = currentSlide.text;
    const highlights = currentSlide.highlights || [];

    if (highlights.length === 0) {
        return text.split(/\s+/).map(w => ({ text: w, isHighlight: false }));
    }

    const escapeRegExp = (string: string) => string.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    const regex = new RegExp(`(${highlights.map(escapeRegExp).join('|')})`, 'g');

    const parts = text.split(regex);
    const finalWords: { text: string; isHighlight: boolean }[] = [];

    parts.forEach(part => {
        if (!part) return;
        const isHighlight = highlights.includes(part);
        const subWords = part.trim().split(/\s+/).filter(w => w.length > 0);

        subWords.forEach(sw => {
            finalWords.push({ text: sw, isHighlight });
        });
    });

    return finalWords;
  }, [currentSlide]);

  const containerVariants: Variants = {
    hidden: { opacity: 0 },
    visible: {
      opacity: 1,
      transition: {
        staggerChildren: 0.06,
        delayChildren: 0.1
      }
    },
    exit: {
      opacity: 0,
      filter: 'blur(10px)',
      scale: 1.05,
      transition: { duration: 0.5, ease: "easeInOut" as const }
    }
  };

  const wordVariants: Variants = {
    hidden: { 
      opacity: 0, 
      y: 40, 
      filter: 'blur(12px)',
      scale: 0.85
    },
    visible: { 
      opacity: 1, 
      y: 0, 
      filter: 'blur(0px)',
      scale: 1,
      transition: { 
        type: "spring" as const,
        damping: 25,
        stiffness: 120,
        mass: 1
      }
    }
  };

  return (
    <AnimatePresence>
      {isVisible && (
        <motion.div
          initial={{ opacity: 1 }}
          exit={{ opacity: 0, filter: 'blur(40px)', scale: 1.05 }}
          transition={{ duration: 0.8, ease: "easeInOut" }}
          className="fixed inset-0 z-[100] bg-[#F9FAFB] flex flex-col items-center justify-center overflow-hidden"
        >
          <div className="relative z-10 w-full max-w-5xl px-8 md:px-12 flex flex-col items-center text-center">
             <AnimatePresence mode="wait">
                <motion.div
                   key={currentSlide.id}
                   variants={containerVariants}
                   initial="hidden"
                   animate="visible"
                   exit="exit"
                   className="flex flex-col items-center"
                >
                   <div className="flex flex-wrap justify-center gap-x-[0.4em] gap-y-3 max-w-4xl mb-8 md:mb-12 perspective-[1000px]">
                      {contentWords.map((wordObj, i) => (
                        <motion.span
                            key={i}
                            variants={wordVariants}
                            className={`inline-block text-4xl md:text-6xl lg:text-7xl font-bold tracking-tight leading-[1.15] md:leading-[1.2] ${
                                wordObj.isHighlight 
                                ? "bg-clip-text text-transparent bg-gradient-to-r from-[#6BAE2E] via-[#2A9D8F] via-[#0872B1] to-[#6BAE2E] bg-[length:300%_auto]" 
                                : "text-gray-900"
                            }`}
                            animate={wordObj.isHighlight ? {
                                backgroundPosition: ["0% center", "300% center"],
                            } : {}}
                            transition={wordObj.isHighlight ? {
                                duration: 8, 
                                repeat: Infinity,
                                ease: "linear"
                            } : {}}
                        >
                            {wordObj.text}
                        </motion.span>
                      ))}
                   </div>

                   {currentSlide.source && (
                       <motion.div 
                          variants={wordVariants}
                          className="flex items-center gap-2"
                       >
                          <div className="h-px w-8 bg-gray-300" />
                          <span className="text-[10px] font-semibold text-gray-400 uppercase tracking-[0.2em]">
                            {currentSlide.source}
                          </span>
                          <div className="h-px w-8 bg-gray-300" />
                       </motion.div>
                   )}
                </motion.div>
             </AnimatePresence>
          </div>

          <motion.div 
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ delay: 0.8, duration: 0.8 }}
            className="absolute bottom-12 left-0 right-0 flex flex-col items-center justify-center gap-6 z-20"
          >
             <div className="flex gap-3">
                {SLIDES.map((_, i) => (
                    <div 
                        key={i}
                        className={`h-1.5 rounded-full transition-all duration-500 ease-out ${
                            i === index 
                                ? 'w-8 bg-gradient-to-r from-[#6BAE2E] to-[#0872B1]'
                                : 'w-1.5 bg-gray-200'
                        }`}
                    />
                ))}
             </div>

             <div className="flex items-center gap-4">
                 <button
                    onClick={handlePrev}
                    disabled={index === 0}
                    className={`w-12 h-12 flex items-center justify-center rounded-full transition-all duration-300 ${
                        index === 0 ? 'opacity-0 pointer-events-none' : 'hover:bg-gray-100 text-gray-500 hover:text-gray-900'
                    }`}
                 >
                    <ArrowLeft size={20} />
                 </button>

                 <button
                    onClick={handleNext}
                    className="group relative flex items-center gap-3 pl-6 pr-5 py-3 bg-gradient-to-r from-[#6BAE2E] to-[#0872B1] text-white rounded-full transition-all duration-300 hover:scale-[1.02] active:scale-95 shadow-xl shadow-[#6BAE2E]/20"
                 >
                    <span className="text-sm font-bold tracking-wide">
                        {index === SLIDES.length - 1 ? "Começar" : "Continuar"}
                    </span>
                    <ChevronRight size={16} className="text-white/80 group-hover:text-white transition-colors" />
                 </button>
             </div>
          </motion.div>
        </motion.div>
      )}
    </AnimatePresence>
  );
};

'use client';

import * as React from 'react';
import { useState, useEffect, useRef } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Sparkles, MapPin, Clock } from 'lucide-react';
import { Testimonial } from '@/lib/constants';

interface ActivityToastsProps {
  isActive: boolean;
  testimonials: Testimonial[];
  onNavigate: (id: string) => void;
  userStory: Testimonial | null;
}

interface NotificationData {
  id: string; 
  name: string;
  age: string; 
  location: string;
  action: string;
  time: string;
}

const ACTIONS = [
  "acabou de partilhar a sua história.",
  "contou a sua história.",
  "partilhou como se sente."
];

export const ActivityToasts: React.FC<ActivityToastsProps> = ({ isActive, testimonials, onNavigate, userStory }) => {
  const [notification, setNotification] = useState<NotificationData | null>(null);
  const countRef = useRef(0);
  const timeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const userStoryShownRef = useRef<string | null>(null);

  const parseAuthor = (authorStr: string) => {
    const parts = authorStr.split(',');
    if (parts.length > 1) {
        return { name: parts[0].trim(), age: parts[1].trim() };
    }
    return { name: authorStr, age: '' };
  };

  const generateNotification = (specificStory?: Testimonial): NotificationData | null => {
    if (specificStory) {
         const { name, age } = parseAuthor(specificStory.author);
         return {
            id: specificStory.id,
            name: name,
            age: age,
            location: specificStory.location,
            action: "acabou de partilhar a sua história.",
            time: "Agora mesmo"
         };
    }

    if (testimonials.length === 0) return null;

    const randomIndex = Math.floor(Math.random() * testimonials.length);
    const story = testimonials[randomIndex];
    const { name, age } = parseAuthor(story.author);
    const randomAction = ACTIONS[Math.floor(Math.random() * ACTIONS.length)];

    return {
      id: story.id,
      name: name,
      age: age,
      location: story.location,
      action: randomAction,
      time: "Agora mesmo"
    };
  };

  useEffect(() => {
    if (userStory && userStory.id !== userStoryShownRef.current) {
        if (timeoutRef.current) clearTimeout(timeoutRef.current);

        const notif = generateNotification(userStory);
        setNotification(notif);
        userStoryShownRef.current = userStory.id;

        timeoutRef.current = setTimeout(() => {
            setNotification(null);
        }, 6000);
    }
  }, [userStory]);

  useEffect(() => {
    if (!isActive) return;

    if (userStory && notification?.id === userStory.id) return;

    const scheduleNext = () => {
      if (countRef.current >= 4) return;

      const isFirst = countRef.current === 0;
      const delay = isFirst 
        ? 1000 
        : Math.floor(Math.random() * 6000) + 4000;

      timeoutRef.current = setTimeout(() => {
        if (userStoryShownRef.current && userStory?.id === userStoryShownRef.current) {
             scheduleNext();
             return;
        }

        const newNotif = generateNotification();
        setNotification(newNotif);
        countRef.current += 1;

        setTimeout(() => {
          setNotification(null);
          scheduleNext();
        }, 5000);
      }, delay);
    };

    scheduleNext();

    return () => {
      if (timeoutRef.current) clearTimeout(timeoutRef.current);
    };
  }, [isActive, userStory]); 

  return (
    <div className="fixed top-24 right-4 md:top-24 md:right-8 z-[60] flex flex-col gap-2 items-end pointer-events-none">
      <AnimatePresence mode="wait">
        {notification && (
          <motion.div
            key={notification.id}
            initial={{ opacity: 0, x: 20, scale: 0.95, filter: 'blur(10px)' }}
            animate={{ opacity: 1, x: 0, scale: 1, filter: 'blur(0px)' }}
            exit={{ opacity: 0, x: 20, scale: 0.95, filter: 'blur(10px)' }}
            transition={{ type: "spring", stiffness: 400, damping: 30 }}
            onClick={() => onNavigate(notification.id)}
            className="pointer-events-auto cursor-pointer bg-white/80 backdrop-blur-xl border border-white/60 shadow-2xl shadow-black/5 rounded-2xl p-4 pr-6 flex items-start gap-3.5 max-w-[280px] md:max-w-xs group hover:bg-white/95 transition-colors"
          >
            <div className="relative shrink-0 mt-0.5">
              <div className="w-8 h-8 rounded-full bg-gradient-to-br from-[#6BAE2E] to-[#2E8B57] flex items-center justify-center text-white shadow-sm">
                <Sparkles size={14} className="fill-white/20" />
              </div>
              <span className="absolute -top-1 -right-1 flex h-2.5 w-2.5">
                <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-green-400 opacity-75"></span>
                <span className="relative inline-flex rounded-full h-2.5 w-2.5 bg-green-500 border border-white"></span>
              </span>
            </div>

            <div className="flex flex-col">
              <div className="flex items-baseline gap-1.5 mb-0.5">
                <span className="text-sm font-bold text-gray-900 leading-none group-hover:text-[#6BAE2E] transition-colors">
                  {notification.name}{notification.age ? `, ${notification.age}` : ''}
                </span>
              </div>

              <p className="text-xs text-gray-600 leading-snug mb-2">
                {notification.action}
              </p>

              <div className="flex items-center gap-3">
                <div className="flex items-center gap-1 text-[10px] font-medium text-gray-400 uppercase tracking-wide">
                  <MapPin size={10} />
                  <span>{notification.location}</span>
                </div>
                <div className="flex items-center gap-1 text-[10px] font-medium text-gray-400 uppercase tracking-wide">
                  <Clock size={10} />
                  <span>{notification.time}</span>
                </div>
              </div>
            </div>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
};

