          `}
          style={!isMobile ? { x: contentX, y: contentY } : {}}
        >
          <div className="pointer-events-auto max-w-xl mx-auto md:mx-0 flex flex-col items-center md:items-start text-center md:text-left">
              <motion.div
                variants={containerVariants}
